function homeHtml(){if(state.pageId==='home'&&state.stateId==='empty')return `<div class="mobile-title"><h1>应用名称</h1><i class="avatar"></i></div><div class="search">⌕　搜索内容或功能</div><div class="empty-state"><section><div class="empty-art"></div><b>暂时没有内容</b><p>这是首页空态，用于演示状态切换。</p><button data-target="core">刷新内容</button></section></div>`;
if(state.pageId==='home')return `<div class="mobile-title"><h1>应用名称</h1><i class="avatar"></i></div><div class="search">⌕　搜索内容或功能</div><section class="app-hero"><small>通用主视觉区</small><h2>一句清晰的页面主张</h2><p>用于承接本期最重要的用户目标。</p><button class="phone-action" data-target="core">开始操作</button></section><div class="section-title"><b>常用功能</b><span>查看全部 ›</span></div><div class="quick-grid"><button class="quick-card" data-target="entry"><i class="fake-icon"></i><b>功能入口 A</b><small>说明文字</small></button><button class="quick-card" data-target="entry"><i class="fake-icon"></i><b>功能入口 B</b><small>说明文字</small></button></div><div class="section-title"><b>推荐内容</b></div><div class="list">${['一条可点击的列表项','另一条通用列表项'].map(t=>`<button class="list-row" data-target="list"><i class="fake-icon"></i><span><b>${t}</b><small>标题、辅助信息与详情入口</small></span><em class="arrow">›</em></button>`).join('')}</div>`;}
